class FirstKSorting {
  public List<Integer> solve(List<Integer> arr, int k) {
    Collections.sort(arr);
    return arr.subList(0, k);
  }
}

class FirstKMinHeap {
  public List<Integer> solve(List<Integer> arr, int k) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>(arr);
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < k; i++) {
      result.add(minHeap.poll());
    }
    return result;
  }
}

class FirstKMaxHeap {
  public List<Integer> solve(List<Integer> arr, int k) {
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>(
        Collections.reverseOrder());
    for (int num : arr) {
      maxHeap.offer(num);
      if (maxHeap.size() > k) {
        maxHeap.poll();
      }
    }
    List<Integer> result = new ArrayList<>();
    while (!maxHeap.isEmpty()) {
      result.add(maxHeap.poll());
    }
    return result;
  }
}

class FirstKQuickselect {
  private Quickselect quickselect = new Quickselect();

  public List<Integer> solve(List<Integer> arr, int k) {
    if (arr.isEmpty()) {
      return new ArrayList<>();
    }
    int kthVal = quickselect.solve(arr, k);
    List<Integer> result = new ArrayList<>();
    for (int x : arr) {
      if (x <= kthVal) {
        result.add(x);
      }
    }
    return result;
  }
}

class Partition {
  public List<List<Integer>> solve(List<Integer> arr) {
    Random rand = new Random();
    int pivot = arr.get(rand.nextInt(arr.size()));
    List<Integer> smaller = new ArrayList<>();
    List<Integer> equal = new ArrayList<>();
    List<Integer> larger = new ArrayList<>();
    for (int x : arr) {
      if (x < pivot) {
        smaller.add(x);
      } else if (x == pivot) {
        equal.add(x);
      } else {
        larger.add(x);
      }
    }
    List<List<Integer>> result = new ArrayList<>();
    result.add(smaller);
    result.add(equal);
    result.add(larger);
    return result;
  }
}

